'use strict';
window.HZLInvestment=(()=>{
const F=window.HZLFinance,M=window.HZLMarketData,$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=(x,d=1)=>x===null||!Number.isFinite(x)?'—':Number(x).toLocaleString('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d}),pct=x=>x===null?'—':(x>0?'+':'')+n(x)+'%',money=x=>n(x/1e7,2),date=d=>new Date(d+'T00:00:00Z').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'});
let tab='capital',ctx={},holdings=[],holdingKind='',holdingFile='',uploadedMarket=null,marketMode='public',seriesA='Zinc',seriesB='Crude oil, Brent',message='';
let capital={capex:120,revenue:180,opex:145,maintenance:3,years:10,tax:25,discount:12,wc:10,revenueGrowth:2,costGrowth:2,terminal:0};
let hedge={side:'Buyer',quantity:5000,spot:2900,strike:2920,ratio:60,fx:84,premium:155,freight:35,depot:1200,feeBps:5,margin:10,funding:9,days:90};let portfolio={priceShock:-10,fxShock:5};
const portCols=['symbol','asset_class','currency','quantity','cost_price','market_price','fx_to_inr','quote_date','previous_price','previous_quote_date','source','eps_ttm','book_value_per_share','annual_dividend_per_share','market_cap','ebitda_ttm','net_debt','fundamentals_date'];
const marketCols=['series','date','value','unit','source','frequency','published_at'];
const samplePortfolio=[['EXAMPLE-METALS','Equity','INR',1000,250,275,1,'2026-10-22',270,'2026-10-21','Synthetic example',20,150,5,27500000000,4000000000,3000000000,'2026-06-30'],['EXAMPLE-GLOBAL','Fund','USD',100,80,85,84,'2026-10-22',84,'2026-10-21','Synthetic example','','','','','','','']];
const csv=(cols,rows)=>cols.join(',')+'\n'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');
const card=(t,s,b)=>`<section class="card"><div class="card-head"><div><h2>${esc(t)}</h2><p>${esc(s)}</p></div></div>${b}</section>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(t=>`<th scope="col">${esc(t)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const metric=(t,v,u,s)=>`<div class="kpi"><div class="kpi-label">${esc(t)}</div><div class="value">${v} <span class="unit">${esc(u)}</span></div><div class="hint">${esc(s)}</div></div>`;
const btn=(text,action,secondary=false)=>`<button class="${secondary?'secondary':''}" data-invest-action="${action}">${esc(text)}</button>`;
function field(key,title,v,{min=0,max=1e8,step='any'}={}){return `<div class="field"><label for="inv-${key}">${esc(title)}</label><input id="inv-${key}" name="${key}" type="number" value="${v}" min="${min}" max="${max}" step="${step}" required></div>`}
const form=(kind,fields,text)=>`<form data-invest-form="${kind}"><div class="form-grid">${fields.join('')}</div><button type="submit">${esc(text)}</button></form>`;
function marketSeries(){return marketMode==='imported'&&uploadedMarket?uploadedMarket.series:M.series}
function monthChange(s,months){const last=s.data.at(-1),d=new Date(last.date+'T00:00:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-months);const key=d.toISOString().slice(0,7),p=s.frequency==='Monthly'?s.data.find(r=>r.date.slice(0,7)===key):null;return p?100*(last.value/p.value-1):null}
function reference(){const s=M.series.find(r=>r.name===(ctx.metal||'Zinc')),oil=M.series.find(r=>r.name==='Crude oil, Brent');return card('Global reference context','Observed monthly averages · September 2026 · released 2 October 2026',`<div class="source-grid"><div><h3>${esc(s.name)} · ${n(s.data.at(-1).value)} ${esc(s.unit)}</h3><p>${pct(monthChange(s,1))} month on month</p></div><div><h3>Brent · ${n(oil.data.at(-1).value)} USD/bbl</h3><p>${pct(monthChange(oil,1))} month on month</p></div><div><h3>World Bank Pink Sheet</h3><p>Monthly reference; not a current executable quote</p><button class="link" data-invest-tab="markets">Explore global trends →</button></div></div>`)}
function cashChart(r){const vals=r.rows.map(x=>x.cumulative),lo=Math.min(0,...vals),hi=Math.max(0,...vals),span=hi-lo||1,x=i=>50+550*i/(vals.length-1),y=v=>220-(v-lo)/span*175;return `<svg class="chart" viewBox="0 0 650 260" role="img" aria-label="Cumulative discounted project cash flow in INR crore"><line x1="50" x2="610" y1="${y(0)}" y2="${y(0)}" stroke="#a5b5a8" stroke-dasharray="4 4"/>${[lo,hi].map(v=>`<text x="4" y="${y(v)+4}">${n(v,0)}</text>`).join('')}<polyline points="${vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}" fill="none" stroke="#176c50" stroke-width="3"/>${vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="#176c50"><title>Year ${i}: ${n(v,2)} INR crore</title></circle>`).join('')}<text x="50" y="246">Year 0</text><text x="565" y="246">Year ${r.rows.length-1}</text></svg>`}
function capitalView(){const p=capital,r=F.project(p),variants=[['Downside',-.1,.05,2],['Base',0,0,0],['Upside',.1,-.02,-1]].map(([name,rev,cost,wacc])=>({name,result:F.project({...p,revenue:p.revenue*(1+rev),opex:p.opex*(1+cost),discount:Math.max(0,p.discount+wacc)}),assumption:`Revenue ${pct(rev*100)}; cost ${pct(cost*100)}; discount ${wacc>=0?'+':''}${wacc}pp`}));return `<div class="context-line">Planning assumptions · unlevered project evaluation · INR crore · annual periods</div><div class="kpis">${metric('Project NPV',n(r.npv,2),'₹ cr','At '+n(p.discount)+'% nominal discount rate')}${metric('Project IRR',r.irr===null?'—':n(r.irr*100),'%',r.irr===null?'No unique conventional IRR':'Annual cash-flow IRR')}${metric('Simple payback',r.payback===null?'Beyond life':n(r.payback),'years','Undiscounted cash recovery')}${metric('Initial funding',n(r.initial,2),'₹ cr','Capex plus initial working capital')}</div>${card('Capital-project assumptions','Editable financial inputs; no project approval implied',form('capital',[field('capex','Initial capex (₹ crore)',p.capex,{min:.01}),field('revenue','Year-1 revenue (₹ crore)',p.revenue),field('opex','Year-1 cash operating cost (₹ crore)',p.opex),field('maintenance','Annual maintenance capex (₹ crore)',p.maintenance),field('years','Project life (years)',p.years,{min:1,max:30,step:1}),field('tax','Tax rate (%)',p.tax,{max:60}),field('discount','Nominal discount rate (%)',p.discount,{max:60}),field('wc','Working capital (% of revenue)',p.wc,{max:100}),field('revenueGrowth','Annual revenue growth (%)',p.revenueGrowth,{min:-50,max:50}),field('costGrowth','Annual operating-cost growth (%)',p.costGrowth,{min:-50,max:50}),field('terminal','After-tax terminal proceeds (₹ crore)',p.terminal)],'Evaluate project'))}<div class="grid equal">${card('Cumulative discounted cash flow','Zero crossing indicates discounted cash recovery',cashChart(r))}${card('Investment case comparison','Explicit sensitivities; no assigned probabilities',table(['Case','NPV ₹ cr','IRR','Assumptions'],variants.map(v=>[v.name,n(v.result.npv,2),v.result.irr===null?'—':n(v.result.irr*100)+'%',esc(v.assumption)]))+`<p class="mini">Discounted payback: ${r.discountedPayback===null?'beyond project life':n(r.discountedPayback)+' years'}. Profitability index: ${n(r.profitabilityIndex,2)}×.</p>`)}</div>${card('Annual cash-flow bridge','Cash flows at each year end, except initial funding at year 0',table(['Year','Revenue','EBITDA','Cash tax','Δ working capital','Terminal + WC recovery','Free cash flow','Discounted FCF'],r.rows.map(v=>[v.year,n(v.revenue,2),n(v.ebitda,2),n(v.tax,2),n(v.wcChange,2),n(v.recovery,2),n(v.cash,2),n(v.discounted,2)]))+`<details><summary>Calculation basis</summary><p>EBITDA = revenue − cash operating costs. Initial capex is depreciated straight-line over project life with zero tax residual. Cash tax = max(0, EBITDA − depreciation) × tax rate; no loss carryforwards. Free cash flow subtracts cash tax, maintenance capex and the change in working capital. Initial working capital is funded at time zero and the final balance is recovered in the last year. Terminal proceeds are already after tax and exclude working capital. Maintenance-capex depreciation, debt financing and interim cash timing are excluded. IRR is omitted for non-conventional cash-flow signs or an unbracketed root. NPV uses the entered nominal discount rate.</p></details>`)}${reference()}`}
function hedgeView(){const p=hedge,r=F.hedge(p),scenarios=[-.2,-.1,0,.1,.2].map(shock=>F.hedge(p,p.spot*(1+shock))),buyer=p.side==='Buyer';return `<div class="context-line">${esc(ctx.metal)} · ${buyer?'Physical buyer / long financial hedge':'Physical producer / short financial hedge'} · scenario settlement</div><div class="kpis">${metric(buyer?'Net procurement cost':'Net sales proceeds',money(r.net),'₹ cr','Physical cash flow plus hedge and costs')}${metric('Hedged volume',n(r.covered,0),'t',n(p.ratio)+'% of physical exposure')}${metric('Residual exposure',n(r.unhedgedTonnes,0),'t','Unhedged metal price exposure')}${metric('Initial margin assumption',money(r.initialMargin),'₹ cr','Liquidity requirement; not an expense')}</div>${card('Physical exposure and hedge assumptions','Matched metal-price settlement; FX and physical basis remain exposed',`<div class="filter-row"><label for="inv-side">Exposure</label><select id="inv-side"><option ${buyer?'selected':''}>Buyer</option><option ${!buyer?'selected':''}>Producer</option></select>${btn('Size from first-month order outlook','order-volume',true)}${btn('Use public monthly metal reference','metal-reference',true)}</div>`+form('hedge',[field('quantity','Physical quantity (tonnes)',p.quantity,{min:.01}),field('spot','Scenario settlement price (USD/t)',p.spot,{min:.01}),field('strike','Hedge entry price (USD/t)',p.strike,{min:.01}),field('ratio','Hedge coverage (%)',p.ratio,{max:100}),field('fx','Settlement FX (INR/USD)',p.fx,{min:.01,step:.01}),field('premium','Physical premium (USD/t)',p.premium),field('freight','Incremental freight (USD/t)',p.freight),field('depot','Depot / delivery cost (INR/t)',p.depot),field('feeBps','Total hedge fees (basis points)',p.feeBps,{max:1000}),field('margin','Initial margin (% of notional)',p.margin,{max:100}),field('funding','Annual margin funding rate (%)',p.funding,{max:100}),field('days','Tenor (days)',p.days,{min:1,max:3650,step:1})],'Calculate hedge scenario'))}<div class="grid equal">${card('Settlement and liquidity bridge','Scenario amounts in INR crore',table(['Component','₹ crore'],[['Physical '+(buyer?'cost':'sales proceeds'),money(r.physical)],['Financial hedge P&L',money(r.hedgePL)],['Hedge fees',money(r.fee)],['Initial-margin funding cost',money(r.financing)],['Adverse financial hedge MTM',money(r.adverseMTM)],[buyer?'Net procurement cost':'Net sales proceeds',`<strong>${money(r.net)}</strong>`]]))}${card('Metal-price sensitivity','−20% to +20% versus entered settlement; FX held fixed',table(['Settlement USD/t','Hedge P&L ₹ cr',buyer?'Net cost ₹ cr':'Net proceeds ₹ cr','Net INR/t'],scenarios.map(v=>[n(v.spot),money(v.hedgePL),money(v.net),n(v.netPerTonne,0)])))}</div>${card('Hedge interpretation','Financial offsets and remaining exposure',`<p>A buyer receives a long-hedge gain when settlement exceeds entry price; a producer receives a short-hedge gain when settlement is below entry price. Net procurement cost subtracts financial gains; net sales proceeds add them. Both include fees and funding cost.</p><details><summary>Scope and assumptions</summary><p>Continuous tonnes, without exchange-contract lot rounding. Financial and physical metal settle against the same scenario price. Premium, freight, depot cost and FX are unhedged. Initial margin is returned and is not deducted as an expense. Funding cost covers initial margin only; daily variation-margin financing, collateral haircuts, counterparty risk, taxes, hedge accounting and execution slippage are excluded. Adverse MTM is an indicative scenario loss, not a broker margin-call forecast. No trade is executed.</p><a href="https://www.lme.com/en/sustainability-and-physical-markets/physical-market-benefits/hedging" target="_blank" rel="noopener noreferrer">LME hedging reference ↗</a></details>`)}${reference()}`}
function portfolioView(){const r=F.portfolio(holdings,portfolio);return card('Portfolio and company fundamentals','Approved holdings and quotes remain in session memory',`<div class="actions">${btn('Download portfolio CSV template','portfolio-template',true)}${btn('Load illustrative portfolio','portfolio-example',true)}${holdings.length?btn('Clear portfolio','portfolio-clear',true):''}</div><label class="upload-label" for="investment-portfolio-file">Import holdings and fundamentals · normalized CSV, up to 2 MB</label><input type="file" accept=".csv,text/csv" id="investment-portfolio-file"><p class="mini">${esc(holdingFile||'Long-only marked positions. No brokerage connection or order execution.')}</p><details><summary>Portfolio data contract</summary><code>${portCols.join(', ')}</code><p>Required fields run from symbol through source. Remaining fields are optional company fundamentals, in the same currency and full currency units. market_cap, EBITDA and net debt must use the same scale. EPS and book value are per share. Annual dividend yield uses the supplied annual dividend per share, not realized income. Supply fundamentals_date whenever a fundamental is included. Quote changes compare the supplied dates and are not necessarily daily. Fund and bond positions are valued at the supplied price per quoted unit.</p></details>`)+(holdings.length?`<div class="context-line">${esc(holdingKind)} · ${holdings.length} positions · all supplied quotes are unverified</div><div class="kpis">${metric('Portfolio market value',money(r.value),'₹ cr','Marked at supplied prices and current FX')}${metric('Unrealized price P&L',money(r.pl),'₹ cr','Cost retranslated at current supplied FX')}${metric('Price return',n(r.returnPct),'%','Excludes income, fees, taxes and FX return')}${metric('Stressed value',money(r.stressed),'₹ cr','Price and FX assumptions below')}</div>${card('Portfolio sensitivity','Common price shock; FX shock applies only to non-INR positions',form('portfolio',[field('priceShock','Price shock (%)',portfolio.priceShock,{min:-99,max:200}),field('fxShock','INR per foreign-currency unit shock (%)',portfolio.fxShock,{min:-99,max:200})],'Revalue scenario')+`<p class="mini">Scenario P&L versus current value: ₹ ${money(r.scenarioPL)} crore. This is a deterministic stress, not value at risk.</p>`)}${card('Holdings valuation','Current quote, comparison date and position economics',table(['Symbol / class','Quote date','Previous date','Quote / currency','FX to INR','Source','Value ₹ lakh','P&L ₹ lakh','Price return','Quote-to-quote'],r.holdings.map(v=>[esc(v.symbol)+'<br><small>'+esc(v.asset_class)+'</small>',esc(v.quote_date),esc(v.previous_quote_date),n(v.market_price,2)+' '+esc(v.currency),n(v.fx_to_inr,2),esc(v.source),n(v.value/1e5,2),n(v.pl/1e5,2),n(v.returnPct)+'%',pct(v.priceChange)])))}${card('Company financial attributes','Ratios shown only where supplied fundamentals support them',table(['Symbol','TTM EPS','P/E','P/B','Annual dividend yield','EV / EBITDA','Fundamentals date'],r.holdings.map(v=>[esc(v.symbol),n(v.eps_ttm,2),v.pe===null?'—':n(v.pe,2)+'×',v.pb===null?'—':n(v.pb,2)+'×',v.dividendYield===null?'—':n(v.dividendYield)+'%',v.evEbitda===null?'—':n(v.evEbitda,2)+'×',esc(v.fundamentals_date||'—')]))+`<p class="mini">P/E excludes non-positive EPS; P/B excludes non-positive book value. EV = supplied market capitalization + net debt. Negative or missing EBITDA does not produce an EV/EBITDA ratio. These attributes are descriptive and do not constitute an investment recommendation.</p>`)}`:`<div class="empty">Import approved positions to calculate portfolio value, price returns and company valuation ratios, or load the labelled illustrative example.</div>`)}
function normalizedChart(){const all=marketSeries(),a=all.find(s=>s.name===seriesA)||all[0],b=all.find(s=>s.name===seriesB)||all[Math.min(1,all.length-1)];if(!a||!b)return '';if(a.frequency!==b.frequency)return '<p>Select series with the same observation frequency for a comparable chart.</p>';const common=a.data.filter(r=>b.data.some(s=>s.date===r.date)).slice(-13);if(common.length<2)return '<p>At least two common observation dates are needed to compare these series.</p>';const ab=a.data.find(r=>r.date===common[0].date).value,bb=b.data.find(r=>r.date===common[0].date).value,A=common.map(r=>({date:r.date,value:100*r.value/ab})),B=common.map(r=>({date:r.date,value:100*b.data.find(s=>s.date===r.date).value/bb})),vals=[...A,...B].map(r=>r.value),lo=Math.min(95,...vals)*.96,hi=Math.max(105,...vals)*1.04,x=i=>50+550*i/(common.length-1),y=v=>220-175*(v-lo)/(hi-lo);return `<svg class="chart" viewBox="0 0 650 265" role="img" aria-label="Two observed price series normalized to 100 on the first common date">${[lo,100,hi].map(v=>`<line x1="50" x2="610" y1="${y(v)}" y2="${y(v)}" stroke="#e3e9df"/><text x="3" y="${y(v)+4}">${n(v,0)}</text>`).join('')}${[A,B].map((rs,j)=>`<polyline points="${rs.map((r,i)=>`${x(i)},${y(r.value)}`).join(' ')}" fill="none" stroke="${j?'#b67c35':'#176c50'}" stroke-width="3" ${j?'stroke-dasharray="7 4"':''}/>${rs.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r.value)}" r="3" fill="${j?'#b67c35':'#176c50'}"><title>${esc(j?b.name:a.name)} · ${esc(r.date)}: ${n(r.value,2)}</title></circle>`).join('')}`).join('')}<text x="50" y="248">${esc(common[0].date)}</text><text x="535" y="248">${esc(common.at(-1).date)}</text></svg><div class="legend"><span><i class="key"></i>${esc(a.name)}</span><span style="color:#946322">┄ ${esc(b.name)}</span><span>First common date = 100 · price-only</span></div>`}
function marketsView(){const ss=marketSeries(),imported=marketMode==='imported',data=imported?uploadedMarket:M,opts=selected=>ss.map(s=>`<option ${s.name===selected?'selected':''}>${esc(s.name)}</option>`).join('');return `<div class="context-line">${imported?'Imported market history · unverified':'Public monthly reference · World Bank Pink Sheet'} · ${ss.length} series · ${imported?'uploaded in this session':'release 2 Oct 2026; observations through Sep 2026'}</div>${card('Global market trend monitor','Prices retain their quoted units; changes require matching calendar-month observations',`<div class="filter-row"><label for="investment-market-mode">Dataset</label><select id="investment-market-mode"><option value="public" ${!imported?'selected':''}>Public monthly reference</option>${uploadedMarket?`<option value="imported" ${imported?'selected':''}>Imported market history</option>`:''}</select></div>`+table(['Series','Latest date','Price','Unit','MoM','3 months','YoY','Frequency'],ss.map(s=>[esc(s.name),esc(s.data.at(-1).date),n(s.data.at(-1).value,2),esc(s.unit),pct(monthChange(s,1)),pct(monthChange(s,3)),pct(monthChange(s,12)),esc(s.frequency)]))+`<p class="mini">Monthly averages are historical observations, not executable spot quotes. Daily imports show levels and chart comparisons; monthly percentage comparisons are omitted.</p>`)}${card('Comparable price trajectories','Last 13 common observations; first plotted date normalized to 100',`<div class="filter-row"><label for="investment-series-a">Series A</label><select id="investment-series-a">${opts(seriesA)}</select><label for="investment-series-b">Series B</label><select id="investment-series-b">${opts(seriesB)}</select></div>`+normalizedChart())}${card('Bloomberg and other licensed market history','Import only data authorized for this use and audience',`<div class="actions">${btn('Download market CSV template','market-template',true)}${btn('Export selected market dataset','market-export',true)}${uploadedMarket?btn('Clear imported market data','market-clear',true):''}</div><label class="upload-label" for="investment-market-file">Import normalized market history · CSV, up to 2 MB</label><input type="file" accept=".csv,text/csv" id="investment-market-file"><p class="mini">Files remain in browser memory. The public application does not gain access to a Bloomberg Terminal or licensed feed.</p><details><summary>Source and connection details</summary><p>Bloomberg Data License supports enterprise data delivery through REST APIs and other channels. A direct connection requires the correct entitlement, service credentials and permitted display rights. No direct Bloomberg feed is connected. Authorized Bloomberg or other vendor exports can be mapped to the CSV contract below; raw vendor formats are not parsed automatically.</p><code>${marketCols.join(', ')}</code><p>Dates use YYYY-MM-DD. Frequency is Daily or Monthly. Monthly observations use calendar month end. Values and dates must match a single consistent unit, source and frequency per series. Publication must be on or after the observation date and no later than 23 October 2026.</p><a href="https://professional.bloomberg.com/products/data/data-license/" target="_blank" rel="noopener noreferrer">Bloomberg Data License ↗</a></details>`)}${card('Data provenance','Inspect sources, timing and transformations',table(['Series','Source','Publication','Definition / coverage'],ss.map(s=>[esc(s.name),esc(s.source),esc(s.published_at),esc(s.definition||'Imported normalized history; original vendor metadata must be verified')]))+(!imported?`<p class="mini">The World Bank: Commodity Price Data (The Pink Sheet), October 2026 workbook. Selected 25 monthly observations per series; monthly changes and normalized comparisons calculated here. Its metadata lists Bloomberg Finance L.P. and other providers for several metal series; this is World Bank redistribution, not a direct Bloomberg feed.</p><div class="actions"><a href="${M.source_url}" target="_blank" rel="noopener noreferrer">Official source ↗</a><a href="${M.workbook_url}" target="_blank" rel="noopener noreferrer">Source workbook ↗</a><a href="${M.license_url}" target="_blank" rel="noopener noreferrer">Data attribution and terms ↗</a></div>`:''))}`}
function render(context){ctx=context;const tabs=[['capital','Capital projects'],['hedging','Procurement & hedging'],['portfolio','Portfolio & companies'],['markets','Global market trends']];return `<div class="investment-tabs" role="group" aria-label="Investment view">${tabs.map(([id,name])=>`<button data-invest-tab="${id}" aria-pressed="${tab===id}" class="${tab===id?'active':'secondary'}">${name}</button>`).join('')}</div><p class="investment-scope">${tab==='hedging'?'Metal and horizon above apply to order-linked exposure sizing. Other hedge inputs are explicit assumptions.':'Financial inputs are independent of the commercial planning horizon. Currency and observation dates are shown within each view.'}</p>${message?`<div class="investment-message" role="status">${esc(message)}</div>`:''}${({capital:capitalView,hedging:hedgeView,portfolio:portfolioView,markets:marketsView})[tab]()}`}
function redraw(){ctx.refresh?.()}
function download(name,data,type='application/json'){const b=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function snapshot(){const base={asOf:'2026-10-23',selectedView:tab};if(tab==='capital')return {...base,classification:'Planning assumptions',assumptions:capital,result:F.project(capital)};if(tab==='hedging')return {...base,classification:'Hedge scenario',metal:ctx.metal,assumptions:hedge,result:F.hedge(hedge)};if(tab==='portfolio')return {...base,classification:holdingKind||'No positions loaded',rows:holdings,scenario:portfolio,result:F.portfolio(holdings,portfolio)};return {...base,classification:marketMode==='imported'?'Imported market history — unverified':'Public monthly reference',market:marketMode==='imported'?uploadedMarket:M}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.investTab){tab=b.dataset.investTab;message='';redraw();window.scrollTo(0,0);return}if(!b.dataset.investAction)return;try{message='';switch(b.dataset.investAction){case 'order-volume':hedge.quantity=ctx.forecast[0].point;message=`Exposure sized to ${n(hedge.quantity,0)} tonnes for ${ctx.metal}, ${ctx.forecast[0].month}.`;break;case 'metal-reference':{const s=M.series.find(s=>s.name===ctx.metal);hedge.spot=s.data.at(-1).value;message=`Applied ${s.name} September 2026 monthly average as a scenario settlement assumption. Hedge entry price remains separate.`;break}case 'portfolio-template':download('HZL-portfolio-template.csv',csv(portCols,samplePortfolio),'text/csv');break;case 'portfolio-example':holdings=F.positions(F.parseCSV(csv(portCols,samplePortfolio)));holdingKind='Synthetic illustrative portfolio';holdingFile='Synthetic example loaded; no real securities or holdings.';break;case 'portfolio-clear':holdings=[];holdingKind='';holdingFile='';break;case 'market-template':download('HZL-market-template.csv',csv(marketCols,[['Example metal','2026-08-31',100,'USD/t','Synthetic template','Monthly','2026-09-02'],['Example metal','2026-09-30',105,'USD/t','Synthetic template','Monthly','2026-10-02']]),'text/csv');break;case 'market-export':download('HZL-market-context.json',marketMode==='imported'?uploadedMarket:M);break;case 'market-clear':uploadedMarket=null;marketMode='public';seriesA='Zinc';seriesB='Crude oil, Brent';break;}redraw()}catch(error){message=error.message;redraw()}});
document.addEventListener('submit',e=>{const form=e.target.closest('form[data-invest-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;const kind=form.dataset.investForm,next={...({capital,hedge,portfolio}[kind])};for(const el of form.querySelectorAll('input'))next[el.name]=Number(el.value);try{if(kind==='capital'){F.project(next);capital=next}else if(kind==='hedge'){F.hedge(next);hedge=next}else {F.portfolio(holdings,next);portfolio=next}message='Financial assumptions recalculated.';redraw()}catch(error){message=error.message;redraw()}});
document.addEventListener('change',async e=>{const id=e.target.id;try{if(id==='inv-side'){hedge.side=e.target.value;redraw()}if(id==='investment-series-a'||id==='investment-series-b'){if(id.endsWith('-a'))seriesA=e.target.value;else seriesB=e.target.value;redraw()}if(id==='investment-market-mode'){marketMode=e.target.value;const s=marketSeries();seriesA=s[0]?.name;seriesB=s[Math.min(1,s.length-1)]?.name;redraw()}if(id==='investment-market-file'||id==='investment-portfolio-file'){const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('CSV exceeds 2 MB.');const raw=F.parseCSV(await file.text());if(id==='investment-portfolio-file'){const validated=F.positions(raw);holdings=validated;holdingKind='Imported portfolio — unverified';holdingFile=file.name+' · '+validated.length+' positions';message='Portfolio validated and valued in session memory.'}else{const rows=F.market(raw),names=[...new Set(rows.map(r=>r.series))],series=names.map(name=>{const group=rows.filter(r=>r.series===name);if(new Set(group.map(r=>r.unit+'|'+r.source+'|'+r.frequency)).size!==1)throw Error('Keep a consistent source, unit and frequency for '+name);if(group[0].frequency==='Monthly'&&group.some(r=>{const d=new Date(r.date+'T00:00:00Z');return d.getUTCDate()!==new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()}))throw Error('Monthly dates must be calendar month ends.');return {name,unit:group[0].unit,source:group[0].source,frequency:group[0].frequency,published_at:group.at(-1).published_at,data:group.map(r=>({date:r.date,value:r.value}))}});uploadedMarket={classification:'Imported market history — unverified',filename:file.name,rows,series};marketMode='imported';seriesA=series[0].name;seriesB=series[Math.min(1,series.length-1)].name;message='Market history validated; vendor entitlement and original data remain unverified.'}redraw()}}catch(error){message='Import rejected: '+error.message;redraw()}});
return {render,snapshot,activeTab:()=>tab,label:()=>tab==='markets'?(marketMode==='public'?'PUBLIC MONTHLY REFERENCE':'IMPORTED MARKET HISTORY'):tab==='portfolio'?(holdings.length?holdingKind.toUpperCase():'PORTFOLIO WORKSPACE'):'FINANCIAL SCENARIOS'};
})();
